    sse_encode_opt_String(self.place, serializer);
    sse_encode_opt_String(self.time, serializer);
    sse_encode_opt_String(self.shortName, serializer);
  }

  @protected
  void sse_encode_today_response(TodayResponse self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.date, serializer);
    sse_encode_list_today_course(self.courses, serializer);
    sse_encode_opt_box_autoadd_failure_code(self.failure, serializer);
    sse_encode_opt_String(self.failureDetail, serializer);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }
